figures.asymptoteSource:
// The complex plane as a picture. The modulus is the segment from the origin
// to the point, the argument is the swept angle, and the conjugate is the same
// point reflected across the real axis.
size(320,300);
pair O = (0,0);
pair z = dir(140) * 2.3;
pair zb = conj(z);
draw(shift(O)*scale(1.25)*unitcircle, gray(0.75));
draw((-2.6,0)--(2.6,0), gray(0.45));
draw((0,-2.6)--(0,2.6), gray(0.45));
draw(O--z, black);
draw(O--zb, dashed);
draw(arc(O, 2.3, 0, 140), gray(0.5));
dot(z, black);
dot(zb, black);
dot(O, black);
label("$z$", z, NW);
label("$\overline{z}$", zb, SW);
label("$|z|$", (O+z)/2 + (-0.3,0.05), NW);
label("$\theta$", dir(70)*0.72, N);
label("$\mathrm{Re}$", (2.55,-0.35), SE);
label("$\mathrm{Im}$", (0.25,2.55), E);

// The six sixth roots of unity, drawn twice. On the left as radii from the
// centre; on the right laid head to tail, where they close into a hexagon and
// the six of them add to zero.
size(360,300);
pair O = (0,0);
draw(shift(O)*scale(1.05)*unitcircle, gray(0.75));
for (int k = 0; k < 6; ++k) {
  pair p = dir(60*k);
  draw(O--p, gray(0.5));
  dot(p, black);
}
pair S = (-3.1,-0.5);
pair q = S;
for (int k = 0; k < 6; ++k) {
  pair r = q + dir(60*k);
  draw(q--r, black);
  q = r;
}
dot(S, gray(0.55));
dot(q, gray(0.55));
label("$1$", O+dir(0), E);
label("$\zeta$", dir(60), NE);
label("$\zeta^{5}$", dir(300), SE);
label("$\sum_{k=0}^{5}\zeta^{k}=0$", S + (0.5,-1.6), S);

// The seven seventh roots of unity as a regular heptagon. Each vertex is one
// rotation of 360/7 degrees from the last, and that spacing is what every
// roots-of-unity picture is made of.
size(320,320);
pair O = (0,0);
pair p0 = dir(90);
pair p1 = dir(90+360/7);
pair p2 = dir(90+720/7);
pair p3 = dir(90+1080/7);
pair p4 = dir(90+1440/7);
pair p5 = dir(90+1800/7);
pair p6 = dir(90+2160/7);
draw(shift(O)*scale(1.15)*unitcircle, gray(0.75));
draw(p0--p1--p2--p3--p4--p5--p6--cycle, black);
dot(p0, black);
dot(p1, black);
dot(p2, black);
dot(p3, black);
dot(p4, black);
dot(p5, black);
dot(p6, black);
label("$\zeta^{0}$", p0*1.2, N);
label("$\zeta^{1}$", p1*1.2, NE);
label("$\zeta^{3}$", p3*1.2, E);
label("$\zeta^{6}$", p6*1.2, NW);

examples.asymptoteSource:
// Successive powers of 1 + i: each multiplication rotates a further 45 degrees
// and multiplies the length by root 2, so the partial products spiral outwards
// along a regular octagon.
size(340,300);
pair O = (0,0);
pair q = O;
for (int k = 1; k <= 4; ++k) {
  pair r = q + dir(45*k)*(1.4142^(k-1));
  draw(q--r, black);
  q = r;
}
draw(shift(O)*scale(2.4)*unitcircle, gray(0.8));
dot(O, black);
dot(q, black);
label("$0$", O, SW);
label("$1+\mathrm{i}$", dir(45)*1.5, NE);
label("$(1+\mathrm{i})^{4}$", q*1.2, E);
label("$\times\sqrt{2},\ +45^\circ$", (-1.2,-2.6), N);

// The fourth roots of -4. Writing -4 as 4 cis 180 degrees and taking fourth
// roots gives four angles spaced 90 degrees apart, at radius root 2, which
// lands exactly on the four points 1+i, -1+i, -1-i and 1-i.
size(320,320);
pair O = (0,0);
pair q1 = (1,1);
pair q2 = (-1,1);
pair q3 = (-1,-1);
pair q4 = (1,-1);
draw((-2.2,0)--(2.2,0), gray(0.45));
draw((0,-2.2)--(0,2.2), gray(0.45));
draw(shift(O)*scale(1.4142)*unitcircle, gray(0.75));
draw(q1--q2--q3--q4--cycle, black);
dot(q1, black);
dot(q2, black);
dot(q3, black);
dot(q4, black);
label("$1+\mathrm{i}$", q1, NE);
label("$-1+\mathrm{i}$", q2, NW);
label("$-1-\mathrm{i}$", q3, SW);
label("$1-\mathrm{i}$", q4, SE);
label("$45^\circ$", dir(22.5)*0.75, E);
